// Capture unified additions before inherited local interactions; one state and one router.
document.addEventListener('click',event=>{
 const source=event.target.closest('[data-full]');
 if(!source){const button=event.target.closest('[data-action]');if(button?.dataset.action==='confirm-reward'){
   const r=state.records.find(x=>x.id===state.activeRecord);if(r&&!r.settled&&r.suggestion){r.confirmedSnapshot={text:r.text,supplement:r.supplement||'',attribute:r.suggestion.attribute,version:r.version,goalId:r.suggestion.goalId};r.settledDay=state.day;save()}
  }if(button?.dataset.action==='submit-feedback'){event.stopImmediatePropagation();const title=$('#feedback-title').value.trim(),text=$('#feedback-text').value.trim();if(!title||!text)return toast('填写标题和内容后再提交。');state.feedback.unshift({id:uid(),username:state.account.username,title,text,day:state.day,reply:''});save();render();return}if(button?.dataset.action==='care-skip'){event.stopImmediatePropagation();state.care[state.day+'@'+button.dataset.id]='今天先跳过';save();render();return}
  if(button?.dataset.action==='enter-admin'){event.stopImmediatePropagation();state.role='admin';save();go('admin');return}
  if(['price','analyze-exception','phase-advice'].includes(button?.dataset.action)&&state.model.source==='off'){event.stopImmediatePropagation();toast('AI 当前已关闭，已保存的记录和手动说明不受影响。');return}
  if(button?.dataset.action==='leave-admin'){event.stopImmediatePropagation();state.role='user';save();go('my');return}
  return
 }
 event.preventDefault();event.stopImmediatePropagation();if(source.disabled)return;const action=source.dataset.full,id=source.dataset.id;
 if(action==='dismiss-notice'){state.notice='';save();render();return}
 if(action==='dismiss-announcement'){state.dismissedNotice=state.noticeData.version;save();render();return}
 if(action==='toggle-care'){state.careVisible=!state.careVisible;save();render();return}
 if(action==='save-event'){const text=$('#event-text').value.trim(),day=$('#content-day').value,intent=$('#analysis-intent').value;if(!text)return toast('先写一点想留下的内容。');if(!day||day>state.day)return toast('请选择今天或更早的日期。');const r=addRecord(text,'event',day,{version:1,sessions:[],analysisIntent:intent});delete state.drafts['event@'+state.day];state.activeRecord=r.id;save();if(intent==='now'){go('record');beginAnalysis(r)}else{render();toast('原文已保存。')}return}
 if(action==='record-filter'){state.filter=id;state.handbookUI.page=0;save();render();return}
 if(action==='search-records'){state.handbookUI={query:$('#handbook-search').value,scope:$('#handbook-scope').value,page:0};save();render();return}
 if(action==='record-page'){state.handbookUI.page+=Number(id);save();render();return}
 if(action==='filter-day'){state.handbookUI={query:'',scope:id,page:0};state.filter='all';go('handbook');return}
 if(action==='analyze')return beginAnalysis(state.records.find(r=>r.id===state.activeRecord));
 if(action==='cancel-analysis'){const r=state.records.find(r=>r.id===state.activeRecord);r.analysisToken=null;r.analysisStatus='idle';save();render();return}
 if(action==='edit-event'){const r=state.records.find(r=>r.id===state.activeRecord);openDialog('编辑原文',`<label class="field">原文<textarea id="edit-event-text">${esc(r.text)}</textarea></label><p class="small muted">保留旧版本与已经确认的依据。未确认的旧分析在原文变化后失效。</p>`,()=>{const text=$('#edit-event-text').value.trim();if(!text)return failDialog('原文不能为空。');if(text!==r.text){(r.revisions ||= []).push({text:r.text,version:r.version});r.text=text;r.version++;if(!r.settled){delete r.suggestion;delete r.clarify;r.analysisStatus='idle';r.analysisToken=null}state.audit.push({type:'编辑原文',record:r.id,version:r.version})}save();closeDialog();render()},'保存原文');return}
 if(action==='record-audit'){const r=state.records.find(r=>r.id===state.activeRecord);openDialog('这条记录的审计',`<p class="small muted">当前原文 v${r.version} · ${r.savedDay} 首次保存</p>${(r.revisions||[]).map(v=>`<p class="quote">原文 v${v.version}：${esc(v.text)}</p>`).join('')}${r.confirmedSnapshot?`<p class="quote">确认时依据：${esc(r.confirmedSnapshot.text)}</p>`:''}<p class="note mt">${r.sameFactAs?'保留了你确认的同事实关联。':'当前没有自动合并其他记录。'}</p>`);return}
 if(action==='revoke-event'){const r=state.records.find(r=>r.id===state.activeRecord);openDialog('撤销这条记录？','<p>原文与历史依据保留，属性不再参与累计，已发金币保留。不会自动删除相关日记。</p>',()=>{r.revoked=true;r.analysisToken=null;state.audit.push({type:'撤销记录',record:r.id});save();closeDialog();render()},'确认撤销');return}
 if(action==='link-fact'){const r=state.records.find(r=>r.id===state.activeRecord),others=state.records.filter(x=>x.id!==r.id&&x.kind==='event'&&!x.revoked);openDialog('由你确认同一件事',`<p class="small muted">内容相似不自动合并。只有确实描述同一次行动，才建立关联。</p><label class="field">选择已有事件<select id="same-fact"><option value="">请选择</option>${others.map(x=>`<option value="${x.id}">${x.contentDay} · ${esc(x.text.slice(0,55))}${x.settled?' · 已入账':''}</option>`).join('')}</select></label>`,()=>{const target=state.records.find(x=>x.id===$('#same-fact').value);if(!target)return failDialog('请选择一条已有事件。');if(r.settled)return failDialog('这条记录已经入账，不能直接改变历史关联。请保留说明并走复核。');if(!target.settled)return failDialog('请先确认作为来源的那条事件，再关联共享结果。');r.sameFactAs=target.id;r.reused=true;r.settled=true;r.award=target.award||0;r.attribute=target.attribute;state.audit.push({type:'同事实关联',record:r.id,target:target.id});save();closeDialog();render()},'确认同一事实');return}
 if(action==='save-diary')return saveFullDiary();
 if(action==='start-review')return startReview();
 if(['answer-review','skip-review','finish-review'].includes(action)){const r=state.records.find(x=>x.id===state.diaryId)||diaryRecord(),s=r.sessions.find(s=>s.id===id),t=s.turns.at(-1);if(action==='finish-review'){if(t.state==='asked')t.state='skipped';finishReview(r,s);return}const text=$('#review-answer')?.value.trim()||'';if(action==='answer-review'&&!text)return toast('可以写一点，也可以跳过。');t.state=action==='skip-review'?'skipped':'answered';t.answer=text;delete state.drafts['review-turn@'+t.id];const next=reviewCandidates(r)[0];if(next&&s.turns.length<4){s.turns.push({id:uid(),topic:next.topic,question:next.text,answer:'',state:'asked'});save();render()}else finishReview(r,s);return}
 if(action==='model-group'){state.modelDraftMemory ||= {};state.modelDraftMemory[state.modelTarget||'primary']=modelDraft;state.modelTarget=id;modelDraft=state.modelDraftMemory[id]||null;save();render();return}
 if(action==='aux-follow'){delete state.auxModel;modelDraft=null;save();render();return}
 if(action==='model-source'){storeEditedModel({...editedModel(),source:id,error:''});save();render();return}
 if(action==='save-model'){const provider=$('#model-provider').value,model=$('#model-name').value.trim(),base=$('#model-base').value.trim();if(!model||!/^https:\/\//.test(base))return toast('请填写完整模型 ID 和 HTTPS 接口地址。');storeEditedModel({source:'own',provider,model,base,status:'unverified',testedModel:'',error:''});modelDraft=null;if(state.modelDraftMemory)delete state.modelDraftMemory[state.modelTarget||'primary'];save();render();toast('配置已保存，尚未证明可用。');return}
 if(action==='test-model'){if(modelDraft)return toast('有未保存修改，请先保存，避免误测旧模型。');const m=editedModel();if(m.source==='off')return toast('AI 已关闭。');m.status='testing';save();render();setTimeout(()=>{m.status=['demo-chat-model','example-chat'].includes(m.model)?'ready':'failed';m.testedModel=m.model;m.error=m.status==='failed'?'模拟：未找到这个模型或没有访问权限。请核对完整模型 ID；不会自动切换模型。':'';save();if(state.route==='models')render()},500);return}
 if(action==='change-password')return changePassword();
 if(action==='request-exemption'){openDialog('记录特殊安排',`<label class="field">日期<input id="exemption-day" type="date" value="${state.day}"></label><label class="field">时段<select id="exemption-period"><option>上午</option><option>下午</option><option>晚上</option><option>全天</option></select></label><label class="field">情况说明<textarea id="exemption-reason" placeholder="例如：陪家人复查，需要调整今天的安排。"></textarea></label><p class="note">这是说明与核对流程，不自动购买娱乐、不改挑战结果，也不为基本休息收费。</p>`,()=>{const day=$('#exemption-day').value,reason=$('#exemption-reason').value.trim(),label=$('#exemption-period').value;if(!day||!reason)return failDialog('填写日期和实际情况。');const advice='说明已保留。必要安排无需先兑换许可；如涉及进行中的挑战，请到挑战里按当时约定核对意外结果。';state.exemptions.push({id:uid(),day,label,reason,advice});save();closeDialog();render()},'保存安排与说明');return}
 if(action==='admin-password')return changePassword(true);
 if(action==='change-email'){openDialog('更换邮箱',`<label class="field">新邮箱<input id="new-email" type="email" value="new-preview@example.com"></label><p class="small muted">正式流程需验证新邮箱；这里只模拟验证链接。</p>`,()=>{const email=$('#new-email').value.trim();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return failDialog('请填写有效邮箱。');closeDialog();openDialog('模拟验证新邮箱',`<p>待验证邮箱：${esc(email)}</p>`,()=>{state.account.email=email;state.account.verified=true;save();closeDialog();render()},'模拟点击验证链接')},'模拟发送验证邮件');return}
 if(action==='logout-devices'){openDialog('退出其他设备？',`<p>将结束 ${state.account.otherDevices} 个其他示例会话，当前浏览器继续使用。</p>`,()=>{state.account.otherDevices=0;save();closeDialog();render()},'确认退出');return}
 if(action==='logout'){state.session=false;authMode='login';go('auth');return}
 if(action==='forgot-password'){authMode='forgot';go('auth');return}
 if(action==='auth-mode'){authMode=id;render();return}
 if(action==='auth-submit'){
  const email=$('#auth-email')?.value.trim(),username=$('#auth-username')?.value.trim();
  if(authMode==='forgot'){if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){$('#auth-error').textContent='请填写有效邮箱。';return}openDialog('请求已受理','<p>如果该邮箱关联可恢复账号，将收到重设说明。这里只模拟流程，不发真实邮件。</p>',()=>{closeDialog();openDialog('设置新的示例密码','<label class="field">新示例密码<input id="recovery-password" type="password" value="demo-recovered-123" autocomplete="off"></label>',()=>{if($('#recovery-password').value.length<12)return failDialog('新密码至少 12 个字符。');authMode='login';closeDialog();render();toast('已完成模拟重设，可以返回登录。')},'完成模拟重设')},'体验重设链接');return}
  if(authMode==='register'){if(!state.site.registration){$('#auth-error').textContent='站点当前暂停注册。';return}if(!username||!/^[a-zA-Z0-9_]{3,30}$/.test(username)||!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||$('#auth-password').value.length<12||$('#auth-confirm').value!==$('#auth-password').value){$('#auth-error').textContent='用户名为 3～30 位字母数字下划线，填写有效邮箱及两次一致、至少 12 位的示例密码。';return}if(state.users.some(u=>u.username===username)){$('#auth-error').textContent='这个示例用户名已存在。';return}openDialog('验证邮箱 · 示例',`<p>${esc(email)}</p><p class="note mt">不需要邀请码。这里只模拟账号验证，新账号进入独立的本机样例工作区，不带入其他账号的记录或金币。</p>`,()=>{state.users.push({id:uid(),username,email,role:'user',status:'active',created:state.day,lastLogin:'',verified:true});save();closeDialog();authMode='login';render();toast('已创建虚构账号，可以体验登录。')},'模拟完成邮箱验证');return}
  if($('#auth-password').value.length<12){$('#auth-error').textContent='示例密码至少 12 个字符。';return}if($('#auth-role').value==='admin'){state.role='admin';state.session=true;go('admin');return}const u=state.users.find(u=>u.username===username&&u.role==='user');if(!u||u.status!=='active'){$('#auth-error').textContent='示例账号不存在或暂时不可用。';return}u.lastLogin=state.day;switchWorkspace(u);state.role='user';state.session=true;go(state.profile.built?'today':'questionnaire');return
 }
 if(action==='preview-export'||action==='download-export'){try{exportDraft=readExport();const file=makeExport(exportDraft);$('#export-error').textContent='';if(action==='download-export')downloadFile(file);else{$('#export-preview').hidden=false;$('#export-preview').textContent=file.text}}catch(e){$('#export-error').textContent=e.message}return}
 if(action==='claim-discovery'){if(state.claims.includes('discovery-deploy'))return;const daily=state.ledger.filter(x=>x.source==='动态成就'&&x.day===state.day).reduce((n,x)=>n+x.amount,0),monthly=state.ledger.filter(x=>x.source==='动态成就'&&x.day>=shift(state.day,-29)).reduce((n,x)=>n+x.amount,0);if(daily+10>40||monthly+10>100)return toast('已达到动态成就试用上限，候选继续保留。');const r=state.records.find(r=>r.settled&&!r.revoked&&/部署/.test(r.text));if(!r)return toast('没有找到满足条件的确认事实。');openDialog('核实这个里程碑',`<p>${esc(r.text)}</p><p class="note mt">示例：首次完成项目部署，奖励 10 币，不额外发属性。同一里程碑只领取一次。</p>`,()=>{ledger(10,'发现型成就 · 首次项目部署','discovery-deploy','动态成就');state.claims.push('discovery-deploy');save();closeDialog();render()},'确认领取');return}
 if(action==='accept-challenge'){const c=state.challenges.find(c=>c.id===id);if(c.status!=='candidate')return;openDialog('接受挑战前看清约定',`<h3>${esc(c.title)}</h3><p class="quote">目标 ${c.target} 次，押金 ${c.deposit} 币；达成后退还押金，并发 ${c.reward} 币挑战奖励。</p><p class="small muted">挑战示例保留旧版合同金额，与新行动奖励分别列账，不把同一事实重复计数。</p>`,()=>{if(state.coins<c.deposit)return failDialog('金币不足以支付押金。');if(c.status!=='candidate')return;c.status='accepted';c.acceptedDay=state.day;ledger(-c.deposit,'接受挑战 · 押金','challenge-deposit:'+id,'挑战押金');save();closeDialog();render()},'确认接受');return}
 if(action==='settle-challenge'){const c=state.challenges.find(c=>c.id===id);if(c.status!=='accepted')return;if(challengeProgress(c)<c.target)return toast('确认过的有效主线行动还不足，可以继续记录，或说明未完成情况。');openDialog('核对挑战达成',`<p>已核实 ${challengeProgress(c)} 次不同的主线事实。退还押金 ${c.deposit} 币，挑战奖励 ${c.reward} 币。</p>`,()=>{if(c.status!=='accepted')return;ledger(c.deposit,'挑战达成 · 退还押金','challenge-refund:'+id,'挑战退款');ledger(c.reward,'挑战达成奖励','challenge-reward:'+id,'挑战奖励');c.status='settled';c.result='已达成，押金和奖励分别入账。';save();closeDialog();render()},'确认结算');return}
 if(action==='abandon-challenge'){const c=state.challenges.find(c=>c.id===id);openDialog('记录未完成或意外',`<label class="field">情况说明<textarea id="challenge-reason"></textarea></label><label class="field">处理方式<select id="challenge-exception"><option value="missed">按原约定放弃，押金不退</option><option value="excused">意外豁免示例，退还押金</option></select></label><p class="small muted">这里只演示原有挑战结果核对，不自动判定用户违规。</p>`,()=>{const reason=$('#challenge-reason').value.trim();if(!reason)return failDialog('请写下情况说明。');if(c.status!=='accepted')return;const excuse=$('#challenge-exception').value==='excused';if(excuse)ledger(c.deposit,'挑战意外 · 退还押金','challenge-refund:'+id,'挑战退款');c.status='abandoned';c.result=(excuse?'意外豁免，已退押金：':'未完成，押金按约定保留：')+reason;save();closeDialog();render()},'确认记录');return}
 if(action==='generate-report'){const days=Number($('#report-period').value),start=shift(state.day,1-days),rows=state.records.filter(r=>r.savedDay>=start&&r.savedDay<=state.day&&!r.revoked);const report={id:uid(),start,end:state.day,title:days===7?'周回顾':'月回顾',text:`这段时间留下 ${rows.filter(r=>r.kind==='event').length} 条事件和 ${rows.filter(r=>r.kind==='diary').length} 篇日记。已有 ${rows.filter(r=>r.settled).length} 条事件完成确认。回看具体行动和感受，选择一个愿意继续的小安排。`,sources:rows.map(r=>({id:r.id,text:r.text,version:r.version}))};openDialog('周期回顾预览 · 模拟',`<p class="quote">${esc(report.text)}</p><p class="small muted">保存报告不新增事件、日记天数或奖励。</p>`,()=>{state.reports.push(report);save();closeDialog();render()},'保存这份回顾');return}
 if(action==='calibrate-anchor'){const a=anchorExamples.find(a=>a[0]===id);openDialog('个人参考校准',`<p>${esc(a[1])}</p><label class="field">参考变化值<input id="anchor-value" type="number" min="0" max="5" step="0.1" value="${state.anchorValues[id]??a[4]}"></label><button class="text-button" data-full="reset-anchor" data-id="${id}">恢复默认参考</button>`,()=>{const v=Number($('#anchor-value').value);if(!Number.isFinite(v)||v<0||v>5)return failDialog('请输入 0～5 的数值。');state.anchorValues[id]=v;save();closeDialog();render()},'保存个人参考');return}
 if(action==='sample-subdimensions'){state.subdimensionSample=true;save();render();return}
 if(action==='propose-subdimensions'){const names=id==='智力'?['逻辑推理','知识应用','学习方法']:['基础能力','实际应用','长期积累'];openDialog('细分方向建议 · 模拟',`<h3>${esc(id)}</h3><p class="small muted">示例名称供你选择，不自动新增或重算主维度。</p>${names.map(n=>`<label class="check-option"><input type="checkbox" name="subdimension" value="${n}" ${(state.subdimensions[id]||[]).includes(n)?'checked':''}>${n}</label>`).join('')}`,()=>{const selected=[...document.querySelectorAll('[name=subdimension]:checked')].map(e=>e.value);if(!selected.length)return failDialog('至少选择一个想保留的方向。');state.subdimensions[id]=selected;save();closeDialog();render()},'确认这些方向');return}
 if(action==='progress-advice'){const main=state.goals.find(g=>g.main),recent=state.records.filter(r=>r.savedDay>=shift(state.day,-6)&&r.settled&&!r.revoked&&r.suggestion?.main);openDialog('近期推进回顾 · 模拟',`<p>当前主线：${esc(main?.title||'尚未选择')}</p><p class="quote">近 7 天有 ${recent.length} 条确认过的主线行动。${recent.length?'可以看看哪些做法有效，给下一次安排留一个明确的小步骤。':'记录较少不代表你没有行动。可以先记下已经做的事，再决定是否缩小下一步安排。'}</p><p class="small muted">这份示例不根据缺少记录认定你偷懒，不自动调整金币、处罚或计划。</p>`);return}
 if(action==='reset-anchor'){delete state.anchorValues[id];save();closeDialog();render();return}
 if(action==='enter-admin'){state.role='admin';go('admin');return}
 if(action==='leave-admin'){state.role='user';go('my');return}
 if(action==='admin-back'){go(adminRoutes.includes(state.adminReturn)?state.adminReturn:'admin');return}
 if(action==='search-users'){state.userFilter={query:$('#user-query').value.trim(),status:$('#user-status').value,role:$('#user-role').value};save();render();return}
 if(action==='manage-user'){const u=state.users.find(u=>u.id===id);if(!u||u.role==='admin')return;const next=u.status==='active'?'disabled':'active';openDialog(next==='disabled'?'停用这个账号？':'恢复这个账号？',`<p>${esc(u.username)}</p><label class="field">原因<textarea id="user-reason"></textarea></label><p class="small muted">保留账号数据，不开放读取其私人记录。</p>`,()=>{const reason=$('#user-reason').value.trim();if(!reason)return failDialog('请填写操作原因。');u.status=next;adminLog(next==='disabled'?'停用账号':'恢复账号',u.username,reason);closeDialog();render()},'确认');return}
 if(action==='preview-notice'||action==='publish-notice'){const title=$('#notice-title').value.trim(),body=$('#notice-body').value.trim();if(!title||!body)return toast('请填写公告标题和内容。');state.noticeDraft={title,body};save();openDialog(action==='preview-notice'?'公告预览':'确认发布公告',`<h3>${esc(title)}</h3><p class="detail-original mt">${esc(body)}</p>`,()=>{if(action==='publish-notice'){state.noticeData={title,body,published:true,version:state.noticeData.version+1};delete state.noticeDraft;adminLog('发布公告',title,'管理员确认发布')}closeDialog();render()},action==='preview-notice'?'返回编辑':'确认发布');return}
 if(action==='withdraw-notice'){openDialog('撤下当前公告？','<p>普通用户首页与公告页将同步隐藏，管理记录保留。</p>',()=>{state.noticeData.published=false;adminLog('撤下公告',state.noticeData.title,'管理员主动撤下');closeDialog();render()},'确认撤下');return}
 if(action==='save-site'){const name=$('#site-name').value.trim();if(!name)return toast('站点名称不能为空。');state.site={...state.site,name,intro:$('#site-intro').value.trim(),registration:$('#site-registration').checked};adminLog('修改站点设置',name,'更新说明或注册开关');toast('站点设置已保存。');return}
 if(action==='reply-feedback'){const f=state.feedback.find(f=>f.id===id),reply=$('#reply-'+id).value.trim();if(!reply)return toast('请先填写回复。');f.reply=reply;adminLog('回复反馈',f.title,'站内私密回复');save();render();return}
},true);
document.addEventListener('input',event=>{if(event.target.dataset.reviewTurn){state.drafts['review-turn@'+event.target.dataset.reviewTurn]=event.target.value;save()}if(['model-name','model-base'].includes(event.target.id))modelDraft={provider:$('#model-provider').value,model:$('#model-name').value,base:$('#model-base').value};if(['notice-title','notice-body'].includes(event.target.id)){state.noticeDraft={title:$('#notice-title').value,body:$('#notice-body').value};save()}});
document.addEventListener('change',event=>{if(event.target.id==='model-provider'){const provider=event.target.value;modelDraft={provider,model:$('#model-name').value,base:providers[provider]?.base||$('#model-base').value};render()}if(event.target.id==='export-format'){exportDraft=readExport();render()}});
document.addEventListener('change',event=>{if(event.target.dataset.dimension){state.dimensionVisibility[event.target.dataset.dimension]=event.target.value;save()}});
if(location.hash)state.route=location.hash.slice(1);
ensureFull();if(state.role==='admin'&&!adminRoutes.includes(state.route)&&state.route!=='guide')state.route='admin';if(state.role!=='admin'&&adminRoutes.includes(state.route))state.route='my';render();
